from pathlib import Path
import json

D=Path(__file__).resolve().parents[2]/'book/source/data'
def save(ident,title,theory,items,anchors):
    tasks=[dict(q=q,a=a,advanced=bool(star)) for q,a,star in items]
    data=dict(id=ident,title=title,theory=theory.strip(),tasks=tasks,art_anchors=anchors)
    (D/(ident+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')

